// Bundled author-facing instructions. IDs are stable; display numbers come from order.
export interface SectionSource {
  id:string; title:string; what:string; when:string; prerequisites:string;
  steps:string[]; example:string; result:string; avoid:string; tags:string[];
  related:string[]; notes?:{title:string;text:string}[];
}
export interface ChapterSource {id:string;title:string;sections:SectionSource[]}
export const chapters:ChapterSource[]=[
 {id:'getting-started',title:'Getting Started',sections:[
  {id:'start',title:'Understanding Notebooks',what:'A notebook is the collection of your Poetry, Philosophy and Lorebook documents. A document is one piece of writing inside that collection. The desktop application opens the active notebook automatically; choosing another studio changes the view, not the notebook.',when:'Read this before your first writing session, or when recovered files do not appear in the library.',prerequisites:'Use the installed desktop app for durable writing and Vault recovery. Browser preview is for exploring the interface.',steps:['Open Settings and find Canonical Content Directory (Markdown). This is the location of the notebook currently in use.','Close Settings and choose Poetry, Philosophy or Lorebook in the sidebar. Select a document in the library to open it.','To use a backup as your notebook, follow Activating a Restored Notebook. Extracting files alone does not change the active notebook.'],example:'One notebook can contain a poem about Eryndor, a reflection about duty and a lore entry for its kingdom. You do not need a separate notebook for each studio.',result:'You can identify the active notebook and distinguish it from the individual documents shown in the library.',avoid:'Do not treat browser preview as durable storage or move notebook folders while the app is writing. A notebook is not a Book in Web of Thought.',tags:['new','library','notebook','desktop'],related:['create-documents','vault-active','file-locations']},
  {id:'create-documents',title:'Creating and Opening Documents',what:'Each document belongs to one writing studio. Its title helps you find it; its body holds your writing. Opening an existing item resumes that document rather than creating a copy.',when:'Start a poem, reflection or worldbuilding entry, or return to unfinished work.',prerequisites:'The desktop notebook has loaded. Close Help before invoking document creation.',steps:["Press Ctrl+N. For Poetry or Philosophy, choose the studio and enter a title. For Lorebook, choose + Create New Universe first, or Add to Existing Universe and select its world and element type.", "After creating a Universe, use its dashboard to add entities or + Add Book. Open a Book to create Chapters; they hold narrative prose rather than planning milestones.", "Write in the newly opened document. To reopen existing work, choose its library row. Use Ctrl+F or Ctrl+K for whole-library search and clear studio, tags or Favorites filters if work seems missing."],example:"Create Universe Eryndor, then add a Faction named Kingdom of Eryndor inside it. Reading the tutorial does not create either record for you.",result:'A new document is stored only after your explicit creation action. Opening it also makes it eligible for Recent.',avoid:'Repeatedly creating a similarly named document is not a way to reopen the original. Search before making a duplicate.',tags:['new','open','create','title','search'],related:['saving','organization','lorebook']},
  {id:'saving',title:'Saving and Organizing Work',what:"Writing can save Automatically or Manually, according to Settings. The save indicator distinguishes pending writing from acknowledged saves. Tags and favorites organize documents without changing their text.",when:'Before closing, switching to recovery, or making a major editing change.',prerequisites:'An open document in the desktop app.',steps:["In Settings → Saving & Autosave Preferences, choose Automatic or Manual. Automatic waits 3 seconds by default, configurable from 1 to 10 seconds.", "In Manual mode, use Save or Ctrl+S. When switching documents/studios or exiting with pending writing, choose Save Changes, Discard Changes or Cancel deliberately.", "If a save fails, keep the app open. Use Ctrl+S or Retry and read the error message. Failed queued planning or organization actions need retry or explicit cancellation; they are not saved merely because you changed views.", "Open Tags beneath the document header to assign labels, or star the document for Favorites. Organization and planning commands persist independently of the writing-save mode.", "Use Ctrl+Q for normal guarded exit. Vault operations flush pending work; a failed save stops the operation. Create and verify a Vault backup before recovery or large external changes."],example:"In Manual mode, finish a reflection, press Ctrl+S and wait for Saved. Changing a tag alone does not mean the pending paragraph has been saved.",result:'The document body and organizational choices are retained. A favorite is a shortcut to the same document, not another copy.',avoid:"Do not force-close after a failed save or treat Manual mode as a pause for all metadata writes. Opening Help neither pauses saving nor creates a backup.",tags:['autosave','retry','exit','save','tags'],related:['organization','vault','errors']},
  {id:'interface',title:'Understanding the Interface',what:'The sidebar chooses a studio, the library lists matching documents, and the main writing area edits the selected item. Settings holds appearance, storage diagnostics and The Vault. Help & Guide is available from navigation.',when:'Find your bearings or adapt the writing space to your screen.',prerequisites:'No document is required to read Help.',steps:['Choose a studio in the sidebar, then an item in the library. Use All, Favorites or Recent with Sort & filter to narrow the list.','Open Settings to choose Charcoal & Gold (Dark), Warm Ivory (Light) or System Match. System follows the operating-system theme.','Choose Help & Guide, Studio guide or F1. Search this manual, expand a chapter and select a numbered section.','Use Previous section / Next section to keep reading, related links to change topics, and Escape or Close Help to return to writing.'],example:'While editing lore, use F1 to open Lorebook guidance. Close Help to return to the existing writing area.',result:'Manual navigation changes what you read, not the selected document or notebook. Open chapters remain expanded while you browse and, during the same app session, after closing Help.',avoid:'A filtered empty library does not mean documents have been deleted. Contextual question marks explain concepts; they do not perform actions.',tags:['interface','theme','light','dark','system','help'],related:['shortcuts','organization','web']},
 ]},
 {id:'poetry-studio',title:'Poetry Studio',sections:[
  {id:'poetry',title:'Writing Poetry',what:'Poetry Studio treats a poem as stanzas with deliberate line breaks. You can shape the arrangement without flattening it into ordinary paragraphs.',when:'Draft verse or revise the order of images and rhythm.',prerequisites:'Create or open a Poetry document.',steps:['Write lines in the stanza writing area. Add a stanza with its add control when you want another group of lines.','Use stanza move controls to change order and its delete control to remove an unwanted stanza. Review before deleting text.','Choose Serif, Sans or Mono for the editing display. Watch the stanza, line and word counts in the toolbar.','Save with Ctrl+S in Manual mode; wait for Saved. Use Import or Export only when you intend to create another document or a file.'],example:'Write a two-line image of a quiet city, then add a second stanza about dawn. Moving the second stanza above the first changes the reading order.',result:'Your stanza text and order are saved as the poem. Display font choices help editing; they are not a print-layout or publishing system.',avoid:'Removing a stanza removes its text. Keep an exported copy or backup before a major revision; there is no revision-history browser.',tags:['verse','poem','stanza','line breaks'],related:['poetry-forms','poem-files','cipher']},
  {id:'poetry-forms',title:'Poetic Forms and Writing Aids',what:'The Form selector records the kind of poem you are working on. Counts and typography provide writing aids, rather than an automatic judge of poetic quality.',when:'Label a sonnet or free verse draft and review its length.',prerequisites:'A Poetry document with some verse.',steps:['Choose a form in Form, such as Free Verse, Rhymed Stanzas or Sonnet.','Review the visible stanza, line and word counts as you edit.','Use Mono if fixed spacing helps you inspect rhythm; read the poem aloud to evaluate meter and rhyme yourself.'],example:'Select Sonnet while drafting fourteen lines. The label describes your intent; it does not enforce fourteen lines or verify a rhyme scheme.',result:'The form selection is retained with the poem. Counts reflect the current writing, not a literary assessment.',avoid:'Do not expect automated scansion, rhyme validation or AI analysis. Those are not controls in the current studio.',tags:['form','sonnet','meter','rhyme','analysis','counts'],related:['poetry','poem-files']},
  {id:'cipher',title:'Emotional Cipher Overview',what:'Emotional Cipher replaces words or phrases to make playful, unfamiliar versions of a poem. This is creative obfuscation, not encryption: a literary transformation rather than protection for private information.',when:'Experiment with language while retaining a way to recover the original, or exchange a transformed poem with another writer.',prerequisites:'Open a nonempty Poetry document and keep the original. The Cipher Key is the exact recovery record for a particular transformed version.',steps:['Choose Emotional Cipher in the Poetry toolbar. Read the preview before saving anything.','Choose Quick Cipher, Random Cipher or Manual Cipher according to how you want substitutions chosen.','Review the mappings and transformed text, then use Save Ciphered Poem & Key to create a separate poem and retain its key.','Use Decode Poem with the matching key to inspect recovered text, and Save Decoded Poem as New Document if you want a recovered document.'],example:'A poem about a river can become a poem about a clock through substitutions. The original stays available when you save the transformed version as a new poem.',result:'Previewing is temporary. Saving produces a new poem bound to the committed Cipher Key. The original document is not replaced by that action.',avoid:'Do not share secrets through Cipher. A .mccipher includes the key, so its recipient can decode it. Losing a key may prevent exact recovery.',tags:['cipher','creative obfuscation','encryption','decode'],related:['cipher-modes','cipher-keys','cipher-sharing']},
  {id:'cipher-modes',title:'Quick, Random and Manual Cipher',what:'Quick swaps words already in the poem. Random substitutes vocabulary from a selected pool. Manual uses your own word or phrase mappings. All three offer previews before you save a transformed copy.',when:'Use Quick for a fast reversal of familiar images, Random for outside vocabulary, or Manual for deliberate symbolic language.',prerequisites:'A poem containing eligible words. Quick needs enough distinct words for pairs; Random needs enough usable vocabulary in its pool.',steps:['For Quick Cipher, set the word count and inspect the displayed swap pairs. Randomize Again creates another roll; save or export a roll before replacing it if you want to keep it.','For Random Cipher, choose the vocabulary pool, set the number of words to transform and inspect Generated Vocabulary Mappings. Reroll Vocabulary changes the result. Import .txt Pool accepts a custom one-word-per-line list.','For Manual Cipher, select a Reusable Dictionary / Manual Key or + Create New Manual Dictionary / Key..., enter Dictionary / Key Name and use Add Rule to add original/replacement pairs. Word-frequency chips can start a mapping.','Review the transformed preview, resolve validation errors, and choose Save Ciphered Poem & Key.'],example:'Quick may swap river ↔ clock when both occur in the poem. For a deliberate river → mirror image, add that pair in Manual and inspect every substitution before saving.',result:'A saved poem receives a key for that particular transformation. A reusable dictionary is a starting set of rules; a poem-specific key also records what happened to that poem.',avoid:'Rerolling does not recreate an old key. The mode, word count or similar dictionary name cannot replace the exact key for an earlier result. Do not ignore ambiguous or invalid mapping warnings.',tags:['quick','random','manual','reroll','pool','dictionary'],related:['cipher-keys','cipher-sharing']},
  {id:'cipher-keys',title:'Cipher Keys and Decoding',what:'A Cipher Key records the substitutions and recovery information associated with a transformed poem. Quick and Random generate a temporary key with their preview; Manual builds one from your chosen rules and the current poem. Saving a ciphered poem or exporting its key/package commits that record to Key Library. Exact matching matters: even the same rules used on different text need not describe the same transformation.',when:'Reopen a saved ciphered poem, move its key to another installation, or investigate a mismatch.',prerequisites:'The saved ciphered text and its matching key. Keep exported originals of both when exchanging files.',steps:['Open the saved ciphered poem and choose its Cipher Key / Decode badge, or open Emotional Cipher → Decode Poem.','Check the selected key. Use Choose Different Key if needed; Import Key (.mckey) brings in a saved key, while Key Library → Use for Decode selects an existing one.','Inspect the decode status and Decoded Original Output. Exact recovery is only established when the matching text and key pass verification.','Choose Save Decoded Poem as New Document to keep the recovered output. Inspect it before treating a partial or legacy decode as your original.','To preserve a standalone key, use Export .mckey on the encoding view or the key export control in Key Library. Retain the file with the corresponding poem.'],example:'Reopen a saved Quick copy, use its Decode badge and recover it with its associated key. If you select the key from a different roll, stop at the mismatch and locate the correct exported key.',result:'Importing a key stores it in Key Library; it does not by itself create a recovered poem. Saving decoded output creates another document.',avoid:'A similar key name is not proof of a match. Do not reroll to solve a missing key. Best-effort decoding is an explicit fallback, not proof of exact recovery. Do not delete a key referenced by saved poems.',tags:['mckey','key library','fingerprint','mismatch','decode','recovery'],related:['cipher-modes','cipher-sharing','poem-files'],notes:[{title:'Why verification can reject edited text',text:'Saved poem-specific keys include information about the transformed text and substitutions. Editing the encoded text can make that record no longer match. Preserve an unedited copy and the exact key; a fingerprint verifies correspondence, not secrecy.'}]},
  {id:'poem-files',title:'Importing and Exporting Poems',what:'Poetry Import and Export move individual poems. Plain Text (.txt) carries stanza text. Markdown (.md) includes frontmatter metadata. Poem Package (.mcpoem) carries poem content and supported metadata. A Cipher Key (.mckey) is a key, while a Cipher Package (.mccipher) bundles encoded text and its exact key.',when:'Bring in existing verse, keep a portable copy, or choose the right format for another writer.',prerequisites:'Use Poetry Studio for poem files and Emotional Cipher for key/package files. Keep the source file.',steps:['Choose Poetry → Import and select .txt, .md or .mcpoem. The import creates a new document and resolves duplicate titles rather than overwriting an existing poem.','Read the imported document and verify line breaks, title and metadata. Poem import has a 5 MB file limit.','Choose Export → Plain Text (.txt), Markdown (.md) or Poem Package (.mcpoem). Locate the resulting file using your desktop download/save behavior.','For exact Cipher sharing, use Emotional Cipher → Export .mccipher instead. Use The Vault for the entire notebook.'],example:'Export a stanza-only .txt for an ordinary text editor, a .mcpoem for richer poem metadata, or a .mccipher when the receiver needs both ciphered poem and exact recovery key.',result:'Import creates notebook content only after you select a file. Export creates a portable file; it does not change which notebook is active.',avoid:'A .mcpoem with cipher metadata is not a substitute for preserving its matching key. None of these poem exports is a full notebook backup. Do not merely rename extensions to convert formats.',tags:['txt','md','mcpoem','mckey','mccipher','import','export'],related:['cipher-sharing','document-files','vault']},
  {id:'cipher-sharing',title:'Sharing .mccipher Packages: Sender to Receiver',what:'A .mccipher is a portable bundle containing the ciphered poem and its exact Cipher Key. It is the convenient way to share a recoverable transformation without asking the receiver to guess which key belongs to it.',when:'Send a transformed poem to another MetaCognition Notebook user, or move it to a second installation.',prerequisites:'Sender: a poem and a valid Cipher preview. Receiver: a Poetry document open so Emotional Cipher is available. Both people should keep the package unchanged.',steps:['Sender: write an original poem, choose Emotional Cipher → Quick Cipher, and review a nonempty transformed preview. Treat the particular preview as the version being shared.','Sender: choose Export .mccipher while that intended preview is still displayed. This preserves its text and exact key together. You may then choose Save Ciphered Poem & Key for a notebook copy; saving opens the newly created document, so do not assume a later encoding preview is still the original result. Keep the original and the exported package.','Sender: deliver that file to the receiver using your chosen file-transfer method. The application does not send messages or upload it for you.','Receiver: open a Poetry document, choose Emotional Cipher → Decode Poem, then Import & Decode (.mccipher) and select the received package.','Review the success notice and recovered poem. This combined action imports the matching key and creates the recovered original document after verification.','If you want to retain the encoded poem first, use Choose Different Key to reveal Import Cipher Package (.mccipher). That action saves the encoded poem and key; review Decode Poem and then Save Decoded Poem as New Document separately.'],example:'Sender transforms a short river poem and exports its current Quick result as river.mccipher. Receiver uses Import & Decode on that file and obtains the verified original as a new poem, without reconstructing the sender’s settings.',result:'The package supplies the key needed for its own text. Import & Decode and Import Cipher Package have different results: recovered original versus stored encoded poem plus key.',avoid:'Do not claim the package is secret: it includes the key. If import or verification fails, keep the file, read the error and request the sender’s unedited export; do not overwrite your original or guess a replacement key.',tags:['sender','receiver','share','mccipher','package','portable'],related:['cipher','cipher-keys','poem-files']},
 ]},
 {id:'philosophy-studio',title:'Philosophy Studio',sections:[
  {id:'philosophy',title:'Freeform Writing',what:'Philosophy Studio starts with space to explore a question in ordinary prose. You do not need to classify your thinking before writing it.',when:'Work through an unfinished thought, reflection or argument.',prerequisites:'Create or open a Philosophy document.',steps:['Write in Freeform Writing. Let paragraphs follow the question rather than choosing reasoning roles first.','When ready, choose Structured Reasoning to inspect individual blocks and assign roles. You can return to the freeform view.','Save with Ctrl+S in Manual mode and wait for Saved before closing. If existing writing already has multiple blocks, edit within them; the view preserves their boundaries.'],example:'Begin with “What makes a promise binding?” and write an uncertain response. You can later identify a premise and objection without rewriting the whole reflection.',result:'Your text saves as the same document. Changing the view changes presentation, not the meaning of your argument.',avoid:'Switching to freeform does not merge separate blocks. There is no automatic argument generation or correctness evaluation.',tags:['freeform','reflection','thinking desk'],related:['reasoning','philosophy-organization','saving']},
  {id:'reasoning',title:'Structured Reasoning',what:'Structured Reasoning gives blocks roles so you can inspect how an argument fits together. Roles describe your writing; they do not prove it.',when:'Separate support, objections and conclusions in a developing reflection.',prerequisites:'A Philosophy document, with or without existing text.',steps:['Choose Structured Reasoning and open About reasoning roles for the meanings of available labels.','Use a block’s role selector to classify existing writing. Use the + role buttons to add new blocks.','Use move up/down to arrange the order, insert below to add a thought nearby, and delete only when you intend to remove that block’s text.','Return to the freeform view to read the whole piece with fewer controls.'],example:'Label “Promises create expectations” as a premise, add an objection about harmful promises, and place your qualified conclusion after it.',result:'Roles and order are retained alongside the text, including when you return to freeform.',avoid:'Deleting a block is an edit, not merely hiding its role. Save a backup before a large restructuring; role labels do not verify logical validity.',tags:['structured','premise','objection','conclusion','argument','roles'],related:['philosophy','saving']},
  {id:'argument-web',title:'Inspecting Arguments with the Argument Web',what:'The Argument Web is a document-local visual thinking and structural inspection tool for Philosophy Studio. It lets you capture argument passages, establish a central Main Thesis, connect arguments with directional relationships (supports, challenges, expands, related), and review non-judgmental structural observations about your reasoning.',when:'Use the Argument Web to examine how reasons connect to a central claim, find disconnected arguments, or verify that captured passages still match your evolving text.',prerequisites:'A Philosophy document with text or arguments. The Argument Web belongs to the active document; it does not connect across different documents.',steps:['In Writing View, highlight any passage in your text. Use "+ Add to Argument Web" on the selection dock to capture it as an argument node, or "Set as Thesis" to make it your central claim.','Switch to the Argument Web tab in the top header. You can pan the canvas by dragging, zoom with scroll or controls, and click "Fit" to view all nodes.','Click any argument node or thesis to open its details in the side inspection panel. Use "Establish Relationship" to connect it to another argument or thesis with Supports (→), Challenges (→), Expands (→), or Related (—).','Review the Document Source Verification badge. If text was moved or modified in your writing, candidate locations are listed; click "Relink Here" to update the source location deliberately.','Open "Structural Insights" to inspect structural observations, such as disconnected arguments or arguments without incoming support. Insights describe graph structure without evaluating philosophical validity or truth.'],example:'Highlight a passage arguing that “Moral responsibility requires alternative possibilities” and add it to the web. Connect it with “Supports →” to a Main Thesis on “Free Will”. If you later edit the essay, use the Argument Web to verify your source passages.',result:'Your Argument Web layout, nodes, relationships, and thesis are preserved directly in document frontmatter metadata. Document prose is never altered by graph edits.',avoid:'The Argument Web never evaluates whether an argument is logically valid, sound, or persuasive. It does not generate counterarguments or replace author judgment.',tags:['argument web','thesis','supports','challenges','reasoning','philosophy','inspection'],related:['philosophy','reasoning','philosophy-organization'],notes:[{title:'Strictly Non-Judgmental Structural Inspection',text:'The tool reports observable graph topology (such as unlinked nodes or source drift). It will never apply automated logical analysis, score arguments, or judge the philosophical validity of your claims.'}]},
  {id:'philosophy-organization',title:'Organizing Philosophical Entries',what:'A reflection uses the same document library, tags and favorites as the other studios. Organizing entries helps you return to a question without introducing a second folder system.',when:'Collect related reflections across several writing sessions.',prerequisites:'One or more Philosophy documents.',steps:['Give each entry a recognizable title through the document header.','Add subject tags in Tags and star frequently revisited reflections.','Choose Philosophy in the sidebar, then combine Favorites or tag filters with sorting or search. Recent follows actual opening history.'],example:'Tag several reflections ethics and promises, then select both tags to find only entries carrying both.',result:'The library narrows to matching documents; bodies and reasoning roles remain intact.',avoid:'Tags are labels, not separate copies. Removing a filter does not remove writing.',tags:['philosophy','tags','organizing','entries'],related:['organization','saving']},
 ]},
 {id:'lorebook-studio',title:'Lorebook Studio & Web of Thought',sections:[
   {id:'lorebook',title:'Universes, Books and Chapters',what:'A Universe is the overarching fictional world. Books are individual stories or volumes set within that Universe. Chapters are the narrative prose documents of a Book. Story Nodes are planning milestones, kept distinct from chapter prose.',when:'Structure your worldbuilding and storytelling into a coherent hierarchy from the start.',prerequisites:"Open Lorebook Studio. If it has no Universe, create one before adding its Books and entities.",steps:['Select Lorebook Studio in the sidebar to open the Universe Dashboard (or Universe Selector). Create or select a Universe to enter its dedicated workspace.','From Universe Dashboard, create worldbuilding entities across 8 categories (+ Add Character, Location, Faction, etc.) or create a new Book with + Add Book.','Inside a Book, create and reorder Chapters for writing narrative prose, or use Story Timeline for planning milestones. When editing in the writing area, the header breadcrumb links back to Universe Dashboard; the document writing toolbar focuses on prose and guided fields rather than acting as a nested folder browser (organize books and chapters from Universe Dashboard instead; the writing toolbar does not offer Book or Chapter label editors).','Legacy documents without a universe assignment remain safely accessible under Unassigned Lore until you assign them.'],example:"Universe Eryndor owns the Faction Kingdom of Eryndor and Book The Fall of Eryndor. The Book contains prose Chapters; its milestones can reference the same faction without making it a Chapter.",result:'The Universe contains your world, Books contain chapters of prose, and Story Nodes track chronological milestones without conflating planning with prose.',avoid:'Renaming a Universe or Book does not rewrite older entry labels. An entry’s Canon status is different from a Book’s continuity setting.',tags:['universe','book','chapter','hierarchy','labels'],related:['lore-entities','web','continuity']},
   {id:'lore-entities',title:'Lore Entities and Attributes',what:'A lore entity is an entry describing something in your world: a character, place, faction, rule, culture, artifact, event, or concept. Its attributes are useful reference facts. A milestone’s World State records what is true at that story moment.',when:'Create the subjects that your timeline and stories will reference.',prerequisites:'A Lorebook document. Read the example freely; create its records only if you choose to practice.',steps:['Create a Lorebook document for your subject directly from Universe Dashboard (+ Add Character, Location, Faction, etc.) or Ctrl+N. Entities created inside a Universe are automatically bound to it.','Write the entry description in the main editor. Collapsible guided attribute fields (such as Role, Species, Affiliation, Climate, or Tenets) appear right below the header alongside custom attributes.','Explore and create connections with other entities using the in-context Relationships & Connections panel directly below the guided fields, without switching between tools.','Timeline milestones and Story Nodes in the Universe or Book can now reference this entity directly. Any unassigned legacy entries can be assigned to a Universe from the Unassigned Lore view.'],example:'Create Kingdom of Eryndor with Region North. Later record status Peaceful at The Golden Age and Destroyed at The Fall in planning; the reference attribute alone does not establish these timeline observations.',result:'The entity belongs directly to its Universe and is immediately available to Book story milestones, timelines, and the World Relationships graph without manual catalog attachment or refresh steps.',avoid:'Do not create duplicate entries to make a missing selector work. A missing or archived reference is retained for inspection. Editing a static attribute does not automatically add a historical change.',tags:['entity','attributes','character','kingdom','faction','attach','refresh'],related:['web','world-state','web-example']},
   {id:'web',title:'Introduction to Web of Thought',what:'Web of Thought is the integrated planning and continuity engine inside Lorebook Studio. Story Nodes represent key narrative milestones. Timelines order those milestones chronologically. World State records an entity’s condition at a milestone, and State Comparison inspects differences between milestones.',when:'You know a beginning and ending but need to discover and structure the middle, or verify continuity across story events.',prerequisites:'Open a Lorebook entry or Universe Dashboard. Planning tools and lore entities are available seamlessly.',steps:["Start from Lorebook → Universe Dashboard. Universe Timeline holds shared history and World Relationships holds the world graph. Books & Stories opens each Book workspace.", "In a Book, use Chapters & Prose for narrative writing and Story Milestones Timeline for simple planning. Its + Add Beginning and + Add Milestone controls create story beats; they are not chapter creation.", "For detailed world-state observations, comparisons and contextual history links, open an entity document and choose Web of Thought in its toolbar. Select the same Universe and Book there, then use Beginner view or Show advanced tools. This desk shares the existing planning records.", "Only Canonical Books can explicitly promote a milestone to shared Universe history. Alternate and Standalone Books retain separate continuity; classification alone never publishes events."],example:'Plan Eryndor’s peaceful beginning and destroyed ending first, then decide whether a betrayal connects them. The app does not invent the missing event or its cause.',result:'A Universe Timeline holds shared world history; a Book Timeline holds one story’s own order and perspective. These are distinct even when a Book links to a shared event.',avoid:'A Story Node is not a Chapter: one milestone might span several chapters, and one chapter might contain several milestones. Do not assume Book events automatically become Universe history.',tags:['story node','timeline','beginner','planning','world state','comparison','unknown state'],related:['story-nodes','world-state','relationships','continuity','shared-events','web-example']},
   {id:'story-nodes',title:'Story Nodes and Timeline Planning',what:'Story Nodes let you plan narrative order without assigning calendar dates. Beginning and ending can be created first; later insertions fill gaps without replacing those records.',when:'Outline a story whose destination is clearer than its route.',prerequisites:"For the controls described below, open a lore entity → Web of Thought, select its Universe and Book, and use Beginner view. The Book workspace has a simpler Story Milestones Timeline.",steps:['Choose Add Beginning Story Node. Select the created milestone and edit Milestone title and Narrative summary / Book perspective.','Choose Add Ending Story Node and edit its title and summary. Date and planning status are optional under Optional date & planning status.','On an existing milestone, choose Insert after to add a moment between it and the next one.','Use the earlier/later arrow controls to reorder. Read comparisons again after moving nodes, since earlier evidence can now appear in a different order.'],example:'Create The Golden Age, then The Fall. On The Golden Age choose Insert after and title the new milestone The Betrayal. The order becomes Golden Age → Betrayal → Fall.',result:'Existing references stay attached to their original milestones when reordered. State views are recomputed from the new order; recorded values and linked entities are not silently rewritten.',avoid:'Reordering can reveal a conflict in a previous-value expectation. It does not invent travel, elapsed time or a causal explanation. Archive and recover milestones deliberately.',tags:['beginning','ending','middle','reorder','insert','chapter','milestone'],related:['world-state','web-example','archive-recovery']},
   {id:'world-state',title:'World-State Changes and Comparisons',what:'World State records an entity’s condition at a selected milestone. A property is a named aspect, such as status or location. State Comparison shows evidence for the same properties at two milestones in one timeline.',when:'Check what changed between your opening and ending, or inspect an apparent contradiction.',prerequisites:"Open an entity → Web of Thought and select the matching Universe/Book. You need a registered entity and two milestones to compare; Book workspace prose is not the comparison editor.",steps:['Select a milestone in Milestones and choose Record entity change. Choose Entity, enter Property (custom keys welcome) and set New value. Add Change explanation if helpful.','For an initial observation, leave Previous value (optional expectation) blank. To record a later transition, you may state what you expected before it.','Select one milestone, choose Compare Story Nodes and choose the other in Compare selected milestone with. Read both column headings to know the direction.','Open Advanced: recorded state & conflicts for the source of evidence or a disagreement with an expected prior value.'],example:'Record status → Peaceful on The Golden Age. Record status with previous expectation Peaceful and new value Destroyed on The Fall. Comparison now has actual observations at both endpoints.',result:'An observation at a node is recorded there. Evidence from earlier nodes may be shown as earlier/uncertain evidence. A blank New value explicitly records unknown, rather than deleting the property.',avoid:'Unknown is not unchanged. Previous value at the ending does not backfill the beginning. If only the ending is recorded, the beginning may remain unknown. No cause is inferred from two different values.',tags:['state','comparison','unknown','conflict','previous value','condition','property'],related:['web-example','story-nodes','relationships'],notes:[{title:'Interpreting uncertainty',text:'A prior observation is evidence about an earlier milestone, not proof of what happened during an unrecorded interval. A conflict flags an expectation that disagrees with earlier evidence. Check order and author-entered records before correcting them; the app does not automatically resolve contradictions.'}]},
   {id:'relationships',title:'Entity Relationships',what:'A relationship connects two lore entities, such as an alliance between factions, a character serving a ruler, or a historical conflict. You can inspect and edit connections directly on an entity page or view the whole world’s graph on the Universe Dashboard.',when:'Track alliances, control, family connections or other relationships through a story.',prerequisites:'Entities in your Universe, accessible on entity pages or the Universe Dashboard.',steps:["Open a lore entity and expand Relationships & Connections. Guided fields such as Character Affiliation and Faction Members also use these same saved links.", "Choose + Add Relationship, Target Entity and Relationship / Role, then choose directed or bidirectional connection and save. Use Member of for Character → Faction, Led by for Faction → Character, or Controls for Faction → Location. Membership never implies leadership.", "Open the other entity to inspect the reciprocal view: Faction Members, Character Leads or Location Controlled by. Allied with and Rival of are symmetric. Select an existing entity, or explicitly create one in this Universe; similar names are not interchangeable IDs.", "Unlink archives the selected connection without deleting either entity. The immediate Undo is available while its panel remains mounted; it rejects a duplicate replacement or a missing endpoint. Later contextual changes belong in Web of Thought milestone observations rather than rewriting the baseline.", "Open Universe Dashboard → World Relationships. Combine relationship/type filters, click a node to focus direct neighbors, then use Open focused entity to navigate. Drag empty canvas to pan; use zoom and Fit. Focus the SVG for arrow-key pan, +/− and Home. The graph draws at most 240 matching edges; inspect the complete records list for the remainder."],example:"Add a Character to Kingdom of Eryndor through Character Affiliation, then open the faction and inspect Members. A separate Led by record establishes leadership; membership alone does not.",result:"Both profiles and the graph read the same acknowledged relationship records. Different kinds and milestone contexts may coexist; equivalent duplicates are rejected.",avoid:'Editing Initial label corrects the original record; it is not a later event. Dashed/unknown evidence is not proof of a connection ending. Failed saves stay queued for Retry or explicit cancellation; they are not confirmed links. Undo refuses an equivalent active replacement and cannot restore a missing entity document. The graph does not invent relationships.',tags:['relationship','graph','directed','label','connections'],related:['world-state','continuity','shared-events']},
   {id:'continuity',title:'Canonical, Alternate and Standalone Books',what:'Continuity describes how a Book relates to shared history. Canonical belongs to the world’s official continuity. Alternate explores a different version. Standalone / Undecided leaves the Book’s shared-history role unestablished.',when:'Keep a speculative or independent story from accidentally publishing world history.',prerequisites:'A selected planning Book.',steps:["In the Book workspace choose Edit Book Details and select Canonical, Alternate or Standalone. The detailed Web of Thought desk also exposes Book continuity, including the Standalone / Undecided wording.", "Keep planning in the Book timeline and writing Chapters. Changing continuity does not publish its milestones.", "If a Canonical milestone should enter shared history, use its explicit promotion action and confirm the named event. Alternate and Standalone Books may reference shared history without promoting milestones."],example:'Keep a “what if Eryndor survived?” story Alternate. The Fall of Eryndor can be Canonical if it describes your official world history.',result:'The Book’s classification changes. Alternate and Standalone Books may link to shared history but cannot promote milestones into it.',avoid:'Entry-level Canon/Draft/Speculative is a different setting. Choosing Canonical alone does not copy events, resolve conflicting facts or affect every Book.',tags:['canonical','alternate','standalone','undecided','continuity'],related:['shared-events','lorebook','web']},
   {id:'shared-events',title:'Shared Universe Events and Promotion',what:'A Shared Universe Event is a milestone in the world’s common history. Several Books can link their own perspectives to that event without replacing their own descriptions.',when:'Different stories refer to the same founding, war or catastrophe.',prerequisites:"For these detailed controls, open an entity → Web of Thought, select its Universe/Book and show advanced tools. You need a Universe event to link, or a Canonical Book milestone to promote.",steps:['In a Book milestone, open Advanced: shared Universe event. Choose an event in Link this Book perspective to existing history.','Use Inspect linked Universe event to read the shared record. Your Book’s perspective remains its own.','To publish a new shared event from a Canonical Book, choose Confirm promotion to Universe history and explicitly confirm the named milestone in the promotion modal.','Review Universe history in the Universe Timeline tab afterward. Promotion copies the summary and world changes while retaining the original Book milestone.'],example:'Promote The Fall from a Canonical Book only if it belongs in Eryndor’s shared history. Another Book can link its own account of the catastrophe to that shared event.',result:'Linking references existing history; promotion creates a new shared event. Book-only relationship changes remain in the Book. Neither action silently merges all Book state into the Universe.',avoid:'Promotion changes shared history, so confirmation is required. Avoid promoting duplicates. A missing/archived event retains its reference; do not assume it was safely replaced by a similarly titled event.',tags:['shared universe event','promote','promotion','history','perspective'],related:['continuity','relationships','story-nodes']},
   {id:'web-example',title:'Tutorial: Plan a Beginning and Ending Before the Middle',what:'This complete example follows a kingdom from peace to destruction. Tutorial only: Eryndor, The Fall of Eryndor and all example records below are instructions, not installed data. Read without clicking data-changing controls, or choose a disposable notebook if you want to create the example.',when:'Try the whole beginning-to-ending workflow without learning technical planning terminology first.',prerequisites:'For reading: none. For practice: desktop app and a deliberate decision to create the example Universe, faction and Book. Save existing work first.',steps:['Use Ctrl+N → Lorebook → + Create New Universe to create Eryndor. In its dashboard, add a Faction named Kingdom of Eryndor, then describe it and save according to your writing mode.','From the Eryndor Universe Dashboard use + Add Book to create The Fall of Eryndor. Chapters & Prose is for narrative writing. For this detailed observation tutorial, reopen Kingdom of Eryndor and choose Web of Thought in its toolbar; select Eryndor and The Fall of Eryndor. The new faction is already registered to its Universe.','In Beginner view choose Add Beginning Story Node. In Milestone title, name it The Golden Age. In Narrative summary / Book perspective write “The kingdom is peaceful.”','With The Golden Age selected, choose Record entity change. Set Entity to Kingdom of Eryndor, Property (custom keys welcome) to status, leave Previous value blank and set New value to Peaceful. This records the beginning itself.','Choose Add Ending Story Node. Set Milestone title to The Fall and summary to “The kingdom is destroyed.” Choose Record entity change, select the kingdom and status, set Previous value to Peaceful and New value to Destroyed.','With The Fall selected, choose Compare Story Nodes, then The Golden Age in Compare selected milestone with. Read the column titles: the ending has Destroyed and the beginning has Peaceful. If the beginning is Unknown, check that its own observation was recorded.','Return to Milestones. On The Golden Age choose Insert after, name the new node The Betrayal and write your intended event. The kingdom’s intervening condition remains for you to decide and record.','Use move earlier/later if needed, then review comparison again. Existing observations, entity references and event links remain on their original nodes; order-sensitive evidence is recalculated. Save with Ctrl+S in Manual mode; wait for Saved.'],example:'Expected sequence: The Golden Age → The Betrayal → The Fall. The beginning records Peaceful; the ending records Destroyed. The new middle is an outline, not an automatically generated explanation of the fall.',result:'You planned two endpoints first and inserted the middle afterward. You can read this entire section without any notebook changes; only your explicit creation/edit actions produce the example.',avoid:'Do not record Peaceful only as the ending’s Previous value and expect it to establish the beginning. Do not mistake Unknown for Peaceful. The app does not invent why the betrayal destroyed the kingdom.',tags:['eryndor','fall','golden age','betrayal','tutorial','beginning','ending','middle','worked example'],related:['lore-entities','story-nodes','world-state','shared-events']},
 ]},
 {id:'manuscript-tools',title:'Manuscript Tools & Assembler',sections:[
   {id:'manuscript-assembler',title:'Assembling Books and Manuscripts',what:'MetaCognition Notebook provides three authoring Studios: Poetry Studio, Philosophy Studio, and Lorebook Studio. Manuscript Tools is a cross-Studio assembly workspace that lets you curate, structure, and bind existing writings across studios into complete manuscripts, anthologies, and collections, rather than a fourth authoring studio. It provides an outline tree with hierarchical section containers, original manuscript prose, and live read-only studio links without mutating source documents.',when:'Gather individual documents into a unified reading volume, organize parts and chapters, or prepare for multi-format export.',prerequisites:'Create or open a Manuscript document. Existing Poetry, Philosophy, or Lorebook documents can be linked at any time.',steps:['Open Manuscript Tools in the sidebar under Cross-Studio Tools and choose "+ Create Manuscript" (or press Ctrl+N while in Manuscript Tools). Provide a title, optional subtitle, author, and tags.','In Outline & Editor, use "+ Add Section" to create structural parts, "+ Link Document" to reference existing studio writings, or "+ Original Prose" for prefaces, introductions, or commentary.','Use the outline tree controls (up, down, indent, outdent) to structure your table of contents and nest items up to 6 levels deep.','Select any linked document in the outline to configure an optional custom title or click "Edit in Studio" to modify the original in its home studio.','Deselect items in the outline to edit manuscript-level metadata (subtitle, author, target word count) and internal project notes.'],example:'Organize a collection with an original Preface, followed by Part I containing five linked poems, and Part II containing three philosophical essays.',result:'Your outline hierarchy and manuscript writing are saved safely in the document frontmatter. Source documents remain untouched.',avoid:'Do not treat Manuscript Tools as a fourth authoring studio or a destructive merge tool. Primary writings belong in Poetry, Philosophy, and Lorebook; linked documents are read-only references whose links survive source renames.',tags:['manuscript','assembler','outline','book','collection','anthology','tree'],related:['manuscript-reading-export','create-documents','document-files']},
   {id:'manuscript-reading-export',title:'Continuous Reading Preview and Export',what:'Reading Preview renders the entire manuscript in unified resolved reading order with a collapsible Table of Contents and real-time word count, page estimation, and reading-time metrics. Export compiles the manuscript directly to Markdown (.md) or printable PDF (.pdf).',when:'Review the continuous flow of your book or generate distributable files for reading and printing.',prerequisites:'An assembled manuscript outline.',steps:['Switch to "Reading Preview" in the manuscript toolbar to view your assembled text with active typography matching each studio type.','Use the collapsible Table of Contents to navigate smoothly across sections, linked poems, and manuscript commentary.','Review live manuscript metrics including total word count, progress toward your target word count, estimated page count, and reading time.','Click "Export..." to open compilation settings. Choose Markdown (.md) for plain-text manuscript archives or PDF (.pdf) for styled documents.','Toggle compilation options including title/cover page, table of contents, and section page breaks. For PDF, choose paper size and typography.','Click Export to save the resulting file directly to disk via the native Windows file save dialog.'],example:'Export an anthology to PDF with Times Serif font, A4 paper size, and an automatically generated Table of Contents.',result:'A clean, formatted Markdown or PDF document is generated locally and saved to your chosen path without altering library state.',avoid:'Do not rely on browser print previews for durable export. Use the native file save dialog to ensure proper output encoding and layout.',tags:['export','pdf','markdown','reading preview','table of contents','word count','pages'],related:['manuscript-assembler','document-files','saving']},
  ]},
 {id:'the-vault',title:'The Vault',sections:[
  {id:'vault',title:'Creating Backups',what:'The Vault saves a verified portable snapshot of your notebook. It protects a collection of writing, unlike an export of one poem. It is a backup utility for all three studios, not another writing studio.',when:'Before recovery, significant edits or a move to another computer.',prerequisites:'The Windows desktop application and enough free space for a backup. Save or retry pending writing first.',steps:['Open Settings → The Vault and choose Create Backup. Pending writing is saved before capture.','Wait for completion and verification. Read the result rather than assuming that an archive filename means success.','Use Open Backup Folder to locate the archive. Keep a verified copy on another drive and retain any earlier backup you may still need.'],example:'Create a backup before revising the Eryndor story structure, then copy the completed .mcbackup to an external drive using your normal file tools.',result:'The backup includes Markdown, organizational and studio metadata, supported attachments, archived deletions and the tag catalog. It does not change the active notebook.',avoid:'A same-drive backup does not protect against drive failure. Backups are not encrypted. Do not mistake a retained interrupted capture for a verified archive.',tags:['vault','backup','mcbackup','create'],related:['vault-verify','vault-separate','vault-active'],notes:[{title:'Format and limits',text:'Format 1 uses an uncompressed ZIP with up to 10,000 files, 64 MiB per file and 1 GiB payload. The document index is rebuilt for recovery. Profile preferences such as Help completion are not portable notebook content.'}]},
  {id:'vault-verify',title:'Verifying Backups',what:'Verification checks a backup before you recover it. The preview lets you inspect the chosen archive so recovery is an explicit decision.',when:'Check a copied archive, an older backup or a file sent from another installation.',prerequisites:'A completed .mcbackup archive.',steps:['In The Vault choose Choose Backup File, or Verify Backup beside a known local backup.','Wait for the Verified result and review the backup preview and counts. Check that this is the intended file.','Choose a recovery action only after verification succeeds. Selection and verification alone do not restore or activate anything.'],example:'Verify an external-drive copy before relying on it. A failed check means you should keep the original file and try another known-good backup.',result:'You have evidence that the chosen archive can be considered for recovery, not proof that it contains every revision you hoped to save.',avoid:'Do not change a file after verifying it and assume the old preview applies. Do not bypass a verification failure or delete your current writing to make room for a restore.',tags:['verify','preview','checksum','corrupt'],related:['vault','vault-separate','vault-safety']},
  {id:'vault-separate',title:'Restoring to a Separate Folder',what:'Separate-folder recovery extracts a verified backup for inspection. Your active library and editor stay on the current notebook.',when:'Look at old Markdown files, compare recovered writing or check a backup without switching notebooks.',prerequisites:'A successfully verified backup preview and a destination parent folder with enough free space.',steps:['Verify the intended archive and review its preview.','In the separate-copy preview, check I reviewed this backup and want to create a separate restored copy. Choose Choose folder & restore separate copy and select the parent folder when prompted.','Wait for completion. Read the displayed recovered folder path and inspect its files.','To display recovered writing as the active notebook in the app, follow Activating a Restored Notebook instead; extraction alone never switches it.'],example:'Extract last week’s backup into a recovery folder to inspect a missing stanza while continuing to use today’s notebook.',result:'Extracted is not activated. The success path tells you where the recovered copy lives; it does not claim the app is displaying that copy.',avoid:'Do not repeatedly restore because the library still shows current documents. That unchanged display is expected for this action.',tags:['restore','separate folder','extracted','inspection'],related:['vault-active','vault-verify','vault-safety']},
  {id:'vault-active',title:'Activating a Restored Notebook',what:'Restore as Active Notebook prepares a validated recovered copy and selects it for use after restart. It preserves the previous notebook rather than overwriting its live files.',when:'You want the app to display and edit the documents from a verified backup.',prerequisites:'A verified intended backup, room for recovery and the pre-switch backup, and readiness to restart. Read every confirmation before proceeding.',steps:['Verify the chosen archive and review the named backup in the active-recovery confirmation.','Confirm explicitly that you want Restore as Active Notebook. Pending changes are saved and current writing is preserved before selection. Editing is blocked during activation.','Wait for the selection/restart screen. Follow its restart instructions; do not keep editing the previous session.','After reopening, inspect the active notebook path and several restored documents. Retain the displayed previous-notebook folder and verified pre-switch backup.','If needed, open The Vault → Return to the previous notebook, confirm the displayed path and choose Return to Previous Notebook. This saves and backs up current writing before another selection/restart.'],example:'Activate last week’s notebook, restart, and see its older Poetry, Philosophy and Lorebook documents. Today’s former notebook remains at the displayed previous path for recovery.',result:'The app uses the selected notebook after restart. The previous folder and pre-switch backup remain recoverable; switching is not an in-place overwrite.',avoid:'Do not confuse a saved selection with a completed restart. Keep all recovery paths if activation fails. Return to Previous Notebook is a switch to the displayed previous folder, not an unlimited history browser.',tags:['active','activate','restart','restore','previous notebook','rollback'],related:['vault-separate','vault-safety','file-locations']},
  {id:'vault-safety',title:'Recovery and Safety Precautions',what:'Recovery must preserve both your present writing and the recovered copy. A failure message is a reason to keep evidence and understand the stage, not to erase files and try to make the interface look successful.',when:'There is insufficient space, a permission error, an interrupted recovery or a startup problem.',prerequisites:'Read the full status and retain displayed paths. Avoid destructive file cleanup.',steps:['If saving fails before backup or activation, keep the app open, fix available space or permissions and retry the save.','If verification or extraction fails, preserve the archive and any retained recovery folder. Try a separate destination or known-good backup only after understanding the failure.','If selection may have been published, follow the restart screen and keep the previous notebook, preserved backup and recovery records. Do not edit both copies assuming they will merge.','If startup is blocked, preserve the original notebook and the Notebooks, Vault and NotebookActivations data before seeking repair. Record the exact message and paths.'],example:'A permissions error during recovery does not justify replacing the live notebook by hand. Preserve all copies, resolve access and use the supported recovery action.',result:'You retain options for inspection, return or repair rather than destroying the only good copy.',avoid:'Do not claim every multi-file operation is atomic. Do not delete recovery evidence or a pre-switch backup as automatic cleanup. Cloud backup and encryption are not enabled.',tags:['disk full','permissions','interrupted','startup','recovery','safety'],related:['vault-active','errors','file-locations']},
 ]},
 {id:'document-management',title:'Document Management',sections:[
  {id:'organization',title:'Tags, Favorites, Recent and Sorting',what:'Tags are reusable labels. Favorites marks important documents. Recent follows when you actually open documents, rather than when you last edited them. These work across all studios.',when:'Find related writing without moving canonical files or building folders.',prerequisites:'At least one document. Recent fills as you open work.',steps:['In an open document, expand Tags, type a new or suggested tag and choose Add. Separate several tags with commas. Remove a document’s tag with its adjacent remove control.','Use Favorite this document or its star to toggle favorite status. Choose Favorites in the library to narrow the list.','Expand Sort & filter, select tags and choose a sort order: last modified, created, title A–Z or Z–A. Every selected tag must match. Combine these with the studio and text search.','Choose Recent for most-recently-opened order. Its ordering follows opening history instead of the regular sort selector. Clear filters if a result seems missing.','Use Manage library tags to Rename a tag across documents or Remove → Remove everywhere. Renaming to an existing tag combines assignments; read the confirmation carefully.'],example:'Mark a poem Favorite and tag it Eryndor and draft. In Poetry → Favorites select both tags to see only favorite poems carrying both labels.',result:'Organizational choices persist without replacing the document body. Opening a document updates Recent even if you never edit its text.',avoid:'Removing a tag from one document differs from Remove everywhere. Recent is not a list of backups or previous versions. An empty filtered list is not evidence of deleted files.',tags:['tags','favorites','recent','sort','filter','rename'],related:['create-documents','archive-recovery','saving']},
  {id:'document-files',title:'Import, Export and Backup: Choosing the Right Action',what:'Poetry supports individual poem Import/Export and Cipher packages. Lorebook has Export Lore for a Markdown file. The Vault handles full-notebook backup and recovery. There is no general all-studio import/export wizard.',when:'Decide whether you need one portable piece of writing or a recoverable notebook.',prerequisites:'An appropriate studio document, or a desktop notebook for The Vault.',steps:['For .txt, .md or .mcpoem poems, use Poetry’s Import / Export toolbar actions.','For matching Cipher text and key, use Emotional Cipher .mccipher actions; use .mckey when only the key is needed.','For a Lorebook entry, choose Export Lore to download its Markdown representation.','For all studios, planning and supported notebook state together, use The Vault → Create Backup.'],example:'A collaborator needs one lore description: Export Lore is appropriate. Moving the entire notebook requires a verified Vault backup and the supported recovery workflow.',result:'The chosen action produces the specific document file or backup you requested; it does not enable a general interchange system for every studio.',avoid:'There is no Philosophy export toolbar or general document import wizard here. Do not assume a poem export contains the rest of your notebook or all keys.',tags:['import','export','formats','lore','backup'],related:['poem-files','cipher-sharing','vault']},
  {id:'archive-recovery',title:'Archiving and Recovery',what:'Deleting a library document archives its Markdown under Backups rather than immediately erasing the file. Planning milestones and relationships have separate archive/recover controls. These are different recovery paths.',when:'Remove an item from everyday view or inspect something archived by mistake.',prerequisites:'Confirm the item and distinguish a writing document from a planning record. Make a Vault backup before manual file repair.',steps:['For a document, use its library Delete document action. A lore entity opens an impact preview listing active relationships and retained milestone references. Review it, optionally create a verified Vault backup, then choose Archive relationships and entity. Other studio documents retain their normal Backups confirmation.','For a milestone, use Delete / archive milestone. Recover it through Archived milestones → Recover milestone in the same timeline.','For a relationship, use Delete / archive relationship. Use Archived relationship records → Recover relationship when editable in the current scope.','There is no document trash/restore browser. Entity archiving first saves relationship archives, then moves the document; an interruption can leave the entity visible with archived links. Retry queued changes finishes retained work; Cancel queued changes and close stops uncompleted stages. Keep Backups and use supported Vault recovery rather than guessing where to copy metadata-bearing files.'],example:'Recovering The Betrayal from Archived milestones restores that planning record. It is not the action for bringing back an archived poem.',result:'Archived planning references remain available. Archived document files are retained on disk, but automatic one-click document unarchive is not implemented. Universe Settings · Danger zone offers a separately confirmed Archive Universe that only hides its selector entry and keeps all content. Inspect or Recover through Archived Universes. Permanent Universe deletion is unavailable.',avoid:'Do not describe this as revision history. Recreating a same-title document does not reconnect the old entity’s references. Never delete Backups casually.',tags:['archive','delete','trash','recover','backups','milestone'],related:['vault-separate','vault-active','file-locations']},
 ]},
 {id:'shortcuts-troubleshooting',title:'Shortcuts and Troubleshooting',sections:[
  {id:'shortcuts',title:'Keyboard Shortcuts',what:'Shortcuts provide quick access to existing writing and Help actions. Native file dialogs have their own Windows behavior.',when:'Navigate while keeping your hands on the keyboard.',prerequisites:'Focus the application; close Help before creating a document.',steps:['F1 opens the current studio guide. Ctrl+N opens document creation. Ctrl+F / Ctrl+K opens whole-library search during normal writing.','Ctrl+S saves or retries pending changes. Ctrl+Q requests the normal safe save-before-exit procedure.','In Help, Ctrl+F / Ctrl+K focuses Search guides. Tab and Shift+Tab move among controls; chapter expanders and optional notes work with Enter or Space. Escape closes Help.','Use section buttons, related links and Previous section / Next section to read. In the walkthrough, Tab reaches Back, Next, Skip and Finish; Show this step reveals/focuses a relevant control without clicking it.'],example:'Open Help & Guide, search unknown state, choose a result labeled with its chapter and section, then Escape to return to writing.',result:'Help contains keyboard focus while open and returns it to the invoking control when that control is still available.',avoid:'Close Help before using Ctrl+N. Ctrl+S and Ctrl+Q retain the normal save/exit behavior, so Help is not a barrier against quitting.',tags:['ctrl','keyboard','tab','escape','f1','accessibility'],related:['interface','troubleshooting']},
  {id:'troubleshooting',title:'Common Problems',what:'Most apparent missing content comes from filters, a different active notebook or an unrecorded planning observation. Check the context before making new data or repairing files.',when:'Writing is missing, an extracted backup seems unchanged, or comparison shows Unknown.',prerequisites:'Keep current writing open if it has not saved.',steps:['Missing document: clear search, tags and Favorites, check the studio, then inspect the active notebook path in Settings.','Recovered files not appearing: separate-folder extraction leaves the app unchanged. Use explicit active recovery and restart if you intend to switch.','Unknown beginning state: record the property at the beginning itself. An ending’s previous-value expectation does not establish an earlier observation.','Entity absent from a selector: check its Universe and Unassigned Lore. New Universe-bound entries register automatically; legacy desk attachment/refresh controls are available in Web of Thought. Missing/archived references are retained, not automatically replaced.','Decode mismatch: locate the exact key and unchanged encoded text, or request the original .mccipher. Do not reroll to approximate a lost key.'],example:'The Fall shows Destroyed but The Golden Age is Unknown. Add the beginning’s Peaceful observation; the app does not invent a middle event to explain the difference.',result:'You can distinguish a view/filter issue from missing evidence, incomplete recovery or an actual save error.',avoid:'Do not reset a planning desk or create duplicates merely to hide a warning. Preserve malformed or duplicate planning data for inspection rather than deleting it.',tags:['missing','unknown state','not showing','mismatch','duplicate','browser preview'],related:['errors','world-state','vault-active','cipher-keys']},
  {id:'errors',title:'Understanding Error Messages',what:'Errors describe the operation that could not finish. Read which stage failed—saving, backup verification, activation, import or planning conflict—before deciding what to retry.',when:'A failure banner, reference warning or conflicting-change message appears.',prerequisites:'Retain your intended text and the exact error message. Avoid closing unsaved work.',steps:['For a failed save, keep the app open and use Ctrl+S / Retry after checking space and access permissions. Failed changes remain pending.','For a planning external-revision conflict, retain your intended edits. Use the workspace control to explicitly cancel failed queued actions, leave/reopen planning, and reapply changes to the current version.','For import/verification errors, keep the source file unchanged and check that you selected the intended format and matching key.','For activation/startup failures, follow the restart/recovery message and preserve every displayed original, staged and backup path.'],example:'A warning that an expected previous value conflicts with earlier evidence is about recorded story facts, not a disk failure. Review timeline order and observations before changing them.',result:'Retry is appropriate only after the cause is addressed. Reading the message does not discard pending writing or repair data automatically.',avoid:'Do not repeatedly reindex to solve a failed write or erase a conflict by deleting the catalog. Best-effort Cipher output is not verified recovery.',tags:['error','failed save','conflict','stale','permissions','disk full'],related:['saving','vault-safety','file-locations'],notes:[{title:'When seeking repair',text:'Record the app version, full error, operation and relevant paths. Preserve copies before repair. The planning desk uses a shared notebook record; conflicting outside edits need reconciliation rather than blind replacement.'}]},
  {id:'file-locations',title:'Data Safety and File Locations',what:'Your desktop notebook stores writing in Markdown files. Settings displays its actual active location and a separate rebuildable search index. Use these paths rather than assuming recovery always uses the default folder.',when:'Make an external copy, find an archived document or explain a startup problem.',prerequisites:'Desktop app. Finish pending saves before copying or editing files externally.',steps:['Open Settings and read Canonical Content Directory (Markdown). The default begins under Documents/MetaCognitionNotebook, but active recovery can select another retained folder.','Read SQLite Rebuildable Index Database for the local index path. Do not overwrite a live database.','Use Reindex from Disk when deliberately rescanning disk changes, after preserving work and resolving pending edits. It rebuilds discovery; it does not recover unsaved text.','Use Open Backup Folder in The Vault for managed archives, and its displayed previous/recovered paths for recovery copies. Retain the notebook’s Backups and Attachments folders.'],example:'After active recovery, the selected notebook path may differ from Documents/MetaCognitionNotebook. Check Settings before deciding that a file is missing.',result:'You know which files the application currently uses and where to preserve copies. Reading Help performs no file or index operation.',avoid:'Do not move canonical paths casually or edit the same notebook externally while the app has pending writes. There is no Drive synchronization, automatic revision history or encrypted backup here.',tags:['paths','markdown','sqlite','index','reindex','storage','locations'],related:['start','vault-safety','archive-recovery'],notes:[{title:'Storage versus preferences',text:'Markdown is canonical document storage and SQLite is the local index. Theme, Help navigation and walkthrough preferences belong to the application profile/session; they are not additional writing documents or automatic sample records.'}]},
 ]},
];
